    full_rows = [(r, row[0]) for r, row in enumerate(grid) if row and all(x == row[0] and x != 0 for x in row)]
    if len(full_rows) >= 2:
        # Repeating sequence is the ordered colors of stripe rows, with the
        # first color occupying the leading run as well.
        period = full_rows[1][0] - full_rows[0][0]
        start = full_rows[0][0] % period
        seq = [0] * period
        for r, color in full_rows:
            seq[r % period] = color
        for k in range(period):
            if seq[k] == 0:
                seq[k] = seq[(k-1) % period] or seq[(k+1) % period]
        return [[seq[(r-start) % period] for _ in range(w)] for r in range(h)]
    # Diagonal guide gives phase of a 3-column repeating texture; the nearby
    # double-width path color fills intervening cells.
    best = (0, None, None)
    for v in nonzero:
        offsets = {c-r for r, row in enumerate(grid) for c, x in enumerate(row) if x == v}
